input.command:
$profiles = @('agent-atlas', 'agent-bolt', 'agent-iris', 'agent-nova', 'agent-rex', 'agent-sage')
$baseDir = "C:\Users\Odyssey Jan Pascual\.claude\profiles"

foreach ($profile in $profiles) {
    $path = Join-Path $baseDir $profile
    if (-not (Test-Path $path)) {
        New-Item -ItemType Directory -Path $path -Force | Out-Null
    }

    $settings = @{
        "`$schema" = "https://json.schemastore.org/claude-code-settings.json"
        model = "auto/best"
        env = @{
            ANTHROPIC_BASE_URL = "http://localhost:20128"
            ANTHROPIC_MODEL = "auto/best"
            CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY = "1"
            CLAUDE_CODE_AUTO_COMPACT_WINDOW = "190000"
        }
    }

    $settings | ConvertTo-Json -Depth 10 | Set-Content (Join-Path $path "settings.json")
    Write-Output "Created: $profile"
}

